import Foundation

// Compiled ONLY by the hand-authored Xcode app project
// (MaqamTrainer.xcodeproj) — this file deliberately lives outside
// Sources/MaqamTrainer so SwiftPM never sees it.
//
// TeacherAudio.swift looks resources up in `Bundle.module` first. That
// accessor is generated by SwiftPM for the SPM build; a plain Xcode app
// target has no resource bundle, because its resources (Assets.xcassets
// and the TeacherAudio/ folder) are copied straight into the .app.
// Pointing `module` at the main bundle makes the same source work
// unchanged in both builds.
extension Bundle {
    static var module: Bundle { .main }
}
